list_tax_country_taxes.code:
import (
	"fmt"
)

resp, err := client.TaxCountryTaxes().ListTaxCountryTaxes(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["country_taxes"].([]any) {
	countryTax := row.(map[string]any)
	fmt.Println(countryTax["id"], countryTax["name"], countryTax["tax_code"], countryTax["tax_rate"], countryTax["tax_method"])
}
fmt.Println(body["pagination"].(map[string]any)["total"])

